function analysisMode(){return session.mode==='analysis'||(!session.mode&&(!!activeVariation||!!session.analysis));}
function switchMode(mode){if(!['play','analysis'].includes(mode))return;cancelTask();if($('gameAction').open){actionKind=null;$('gameAction').close();}session.mode=mode;selected=null;save();render();if(mode==='play')void computer();}
$('appMode').onchange=e=>switchMode(e.target.value);
function moveBlocked(){return viewedGame().isGameOver()||(!browsing()&&gameEnded());}
function jumpNotation(id,ply){save();if(saveFailed)return;cancelTask();activeVariation=id||null;game=variationGame(session,activeVariation);replayCursor=ply;selected=null;ensureVariantChat();const last=viewedGame().history({verbose:true}).at(-1);lastText=last?explain(last,viewedGame(),lang):t('Ausgangsstellung.','Starting position.');save();render();}

function importedEnd(){return !activeVariation&&['1-0','0-1','1/2-1/2'].includes(session.sourceResult)&&game.fen()===session.sourceFinalFen&&game.history({verbose:true}).map(uci).join(' ')===session.sourceUci;}
function gameEnded(){return game.isGameOver()||!activeVariation&&!!declaredOutcome(session,game)||importedEnd();}
function endedText(){return outcomeText(session,game,lang)||(importedEnd()?t(session.sourceResult==='1-0'?'Weiß gewinnt (PGN-Ergebnis).':session.sourceResult==='0-1'?'Schwarz gewinnt (PGN-Ergebnis).':'Remis (PGN-Ergebnis).',session.sourceResult==='1-0'?'White wins (PGN result).':session.sourceResult==='0-1'?'Black wins (PGN result).':'Draw (PGN result).'):resultText(game,lang));}
let lcdClient=null,lcdEpoch=0,lcdFen=null,lcdEvaluation=null,lcdError=false,lcdState='loading',lcdMode=0,lcdRenderTimer=null;
