const lcdScreen=createLcdFullscreen({language:()=>lang,onMode:mode=>{lcdMode=mode;save();},onTime:time=>{$('lcdAnalysisTime').value=analysisTime(time);cancelLcd();save();renderLcd();},onContinuous:enabled=>{$('lcdContinuous').checked=enabled;cancelLcd();save();renderLcd();}});
