const importer=createPositionImport({language:()=>lang,onFeedback:text=>speak(text),onOpen:()=>{lcdScreen.close();save();cancelTask();},onClose:()=>{finishIncoming();render();if(!activeVariation&&!browsing()&&gameEnded())void reviewGame();else void computer();},onImport:({fen,analysis,human:color})=>{save();if(saveFailed)return false;cancelTask();const next=newSession(color);next.startFen=fen;next.analysis=analysis;setActive(next);chat('system',t('Geprüfte Stellung übernommen. Bewertungen und Zusammenfassung beziehen sich auf die Fortsetzung ab dieser Stellung.','Checked position imported. Evaluations and summary cover the continuation from this position.'));save();render();return true;}});
$('importPosition').onclick=()=>importer.open();
const textImporter=createTextImport({language:()=>lang,onOpen:()=>{lcdScreen.close();save();cancelTask();},onClose:()=>{finishIncoming();render();if(!activeVariation&&!browsing()&&gameEnded())void reviewGame();else void computer();},onImport:parsed=>{save();if(saveFailed)return false;cancelTask();const next=transferredSession(parsed),replay=new Chess(next.startFen);next.chat.push({kind:'system',text:t('Geteilte Partie/Stellung importiert. Die vollständige Hauptvariante bleibt beim Durchgehen erhalten.','Shared game/position imported. Browsing retains the complete main line.'),lang,at:next.created});for(const [i,m]of next.moves.entries()){const move=replay.move(m);next.chat.push({kind:'move',ply:i+1,number:Number(move.before.split(' ')[5]),color:move.color,san:move.san,fen:move.after,move:moveObject(move),text:explain(move,replay,lang),lang,at:next.created});}setActive(next);save();return true;}});
