window.sharedImportError=code=>notify(code==='too_large'?t('Die geteilte Datei ist zu groß. Bitte eine einzelne PGN/FEN-Datei teilen.','Shared file too large. Share a single PGN/FEN file.'):code==='multiple_files'?t('Bitte jeweils ein Bild oder eine PGN/FEN-Datei teilen.','Share one image or PGN/FEN file at a time.'):t('Geteilte Datei konnte nicht gelesen werden. Bitte Bild, PGN oder FEN mit Lesefreigabe teilen.','Could not read shared content. Share an image, PGN or FEN with read permission.'));
