function viewedGame(){return replayCursor===null?game:gameAtPly({...session,moves:game.history({verbose:true}).map(moveObject)},replayCursor);}
function browsing(){return replayCursor!==null&&replayCursor<game.history().length;}
function moveReplay(ply){if(reviewing&&analysisMode())cancelTask();if(busy&&!reviewing){generation++;client?.abort();client=null;busy=false;}cancelLcd();cancelCoach();selected=null;replayCursor=Math.max(0,Math.min(game.history().length,ply));const view=viewedGame(),last=view.history({verbose:true}).at(-1);lastText=last?explain(last,view,lang):t('Ausgangsstellung.','Starting position.');if(window.Android?.stop)Android.stop();save();render();if(!browsing()&&!reviewing)void computer();}
function renderReplay(){const length=game.history().length,ply=replayCursor===null?length:replayCursor;$('replayControls').hidden=false;$('analyzeGame').hidden=!analysisMode()||!!activeVariation;$('replaySlider').max=length;$('replaySlider').value=ply;$('replayStart').disabled=$('replayPrev').disabled=ply===0;$('replayNext').disabled=$('replayEnd').disabled=ply===length;$('replayState').textContent=t(`Ansicht: ${ply} von ${length} Halbzügen. ${analysisMode()?'Abweichende Züge werden automatisch als Variante gespeichert.':''}`,`Viewing: ${ply} of ${length} half-moves. ${analysisMode()?'Different moves are saved as variations automatically.':''}`);$('analyzeGame').disabled=reviewing;renderVariations();$('notationCard').hidden=!analysisMode();$('notationLabel').textContent=t('PGN · ZUM ZUG SPRINGEN','PGN · SELECT A MOVE');if(analysisMode())renderNotation($('notation'),session,activeVariation,ply,jumpNotation,lang);}
$('replaySlider').oninput=e=>moveReplay(Number(e.target.value));$('replayStart').onclick=()=>moveReplay(0);$('replayPrev').onclick=()=>moveReplay((replayCursor??game.history().length)-1);$('replayNext').onclick=()=>moveReplay((replayCursor??game.history().length)+1);$('replayEnd').onclick=()=>moveReplay(game.history().length);$('analyzeGame').onclick=()=>void reviewGame({force:true});

function renderVariations(){const select=$('variationSelect');select.replaceChildren();const main=document.createElement('option');main.value='';main.textContent=t('Hauptvariante','Main line');select.append(main);for(const v of session.variations||[]){const option=document.createElement('option');option.value=v.id;option.textContent=(v.parentId?'↳ ':'')+t('Variante ','Variation ')+((session.variations||[]).indexOf(v)+1)+' · '+v.moves.length+t(' Halbzüge',' half-moves');select.append(option);}select.value=activeVariation||'';const ply=replayCursor??game.history().length;$('variationNew').disabled=ply>=game.history().length||viewedGame().isGameOver();$('variationMain').disabled=!activeVariation;$('variationDelete').hidden=!activeVariation;$('variationHelp').textContent=activeVariation?t('Analysevariante: beide Seiten eingeben. Die Hauptpartie bleibt erhalten. Für eine weitere Abweichung einen Halbzug zurückgehen.','Analysis variation: enter both sides. The main game is preserved. Go back a half-move for another alternative.'):t('Im Analyse-Modus zur gewünschten Stellung gehen und einen anderen Zug eingeben: Der Abzweig entsteht automatisch. Varianten werden mit der Partie gespeichert und als PGN-Klammerzweige exportiert.','In analysis mode, browse to a position and enter a different move to create a branch automatically. Variations are saved with the game and exported as PGN branches.');}
function ensureVariantChat(){if(!activeVariation||session.chat.some(e=>e.kind==='move'&&e.variationId===activeVariation))return;const v=session.variations.find(v=>v.id===activeVariation),replay=new Chess(session.startFen);for(const [i,m]of variationMoves(session,activeVariation).entries()){const played=replay.move(m);if(i<v.basePly)continue;const note=v.comments?.find(c=>c.ply===i+1)?.text;chat('move',explain(played,replay,lang)+(note?'\n'+note:''),{ply:i+1,fen:played.after,san:played.san,number:Number(played.before.split(' ')[5]),color:played.color,move:moveObject(played)});}}
function selectVariation(id){save();if(saveFailed)return;cancelTask();activeVariation=id||null;game=activeVariation?variationGame(session,activeVariation):restoreGame(session);replayCursor=null;selected=null;const last=game.history({verbose:true}).at(-1);lastText=last?explain(last,game,lang):'';ensureVariantChat();save();render();if(!activeVariation&&gameEnded())void reviewGame();else void computer();}
$('variationSelect').onchange=e=>selectVariation(e.target.value);$('variationMain').onclick=()=>selectVariation(null);$('variationNew').onclick=()=>{if($('variationNew').disabled)return;const ply=replayCursor??game.history().length;save();if(saveFailed)return;cancelTask();session.mode='analysis';try{const v=createVariation(session,activeVariation,ply);activeVariation=v.id;game=variationGame(session,v.id);replayCursor=null;selected=null;const last=game.history({verbose:true}).at(-1);lastText=last?explain(last,game,lang):t('Ausgangsstellung.','Starting position.');$('entry').value='';chat('system',t('Neue Analysevariante angelegt. Die Hauptvariante bleibt unverändert.','New analysis variation created. The main line is preserved.'));save();render();}catch(e){notify(t('Variante konnte nicht angelegt werden: ','Could not create variation: ')+e.message);render();}};
function closeAction(){actionKind=null;$('gameAction').close();render();void computer();}
function openAction(kind){if(kind!=='delete'&&($('resign').disabled||$('offerDraw').disabled))return;cancelTask();actionKind=kind;$('resignSideLabel').hidden=kind!=='resign'||!analysisMode();$('resignSide').value=analysisMode()?game.turn():human;$('actionTitle').textContent=t(kind==='resign'?'Partie aufgeben?':kind==='draw'?'Remis vereinbaren?':'Variante löschen?',kind==='resign'?'Resign game?':kind==='draw'?'Agree draw?':'Delete variation?');$('actionText').textContent=t(kind==='delete'?'Dieser Zweig und seine Untervarianten werden gelöscht. Die Hauptpartie und der gesamte Chat bleiben erhalten.':kind==='resign'?'Die Partie wird mit dem Ergebnis der Aufgabe gespeichert. Du kannst sie danach weiter nachspielen und Varianten analysieren.':'Für diese Analysepartie wird ein vereinbartes Remis gespeichert.',kind==='delete'?'This branch and its subvariations will be deleted. The main game and full chat are retained.':kind==='resign'?'The resignation result is saved. You can still replay the game and analyze variations.':'A draw by agreement will be saved for this analysis game.');$('gameAction').showModal();}
function finishGame(reason,color=human){cancelTask();replayCursor=null;finishOutcome(session,game,reason,color);const text=outcomeText(session,game,lang);chat('system',text);save();render();if(session.review?.status==='complete'){const parts=buildSummaryParts(session,lang),summary=buildSummary(session,lang);chat('summary',summary,{parts});save();render();speak(summary);}else{speak(text);void reviewGame();}}
$('resign').onclick=()=>openAction('resign');$('variationDelete').onclick=()=>openAction('delete');$('actionCancel').onclick=closeAction;$('gameAction').oncancel=e=>{e.preventDefault();closeAction();};$('actionConfirm').onclick=()=>{const kind=actionKind,color=$('resignSide').value;actionKind=null;$('gameAction').close();if(kind==='delete'){const id=activeVariation,parent=session.variations.find(v=>v.id===id)?.parentId||null;cancelTask();deleteVariation(session,id);activeVariation=parent;game=variationGame(session,parent);replayCursor=null;chat('system',t('Variante gelöscht; der Chat bleibt erhalten.','Variation deleted; conversation retained.'));save();render();}else finishGame(kind==='draw'?'agreement':'resignation',color);};
$('offerDraw').onclick=async()=>{if($('offerDraw').disabled)return;if(analysisMode()){openAction('draw');return;}cancelTask();const token=generation,fen=game.fen(),engine=new StockfishClient();client=engine;busy=true;chat('system',t('Du bietest Remis an. Stockfish bewertet das Angebot.','You offer a draw. Stockfish is evaluating the offer.'));save();render();let evaluation;try{const result=await engine.search(game.history({verbose:true}).map(uci),game.turn(),{skill:20,nodes:12000,fen:session.startFen});evaluation=result.evaluation;}catch{}finally{engine.abort();if(token===generation){client=null;busy=false;}}if(token!==generation||game.fen()!==fen)return;if(!evaluation){notify(t('Remis-Angebot konnte nicht bewertet werden. Die Partie läuft weiter.','Could not evaluate the draw offer. The game continues.'));render();void computer();return;}if(acceptsDraw(evaluation,human)){finishGame('agreement');return;}const text=t('Stockfish lehnt das Remis-Angebot wegen seines Stellungsvorteils ab. Die Partie läuft weiter.','Stockfish declines the draw offer because it has a positional advantage. The game continues.');chat('system',text);save();render();speak(text);void computer();};

function assessMoveSpeech(evaluation){const item=pendingSpeechAssessment;if(!item||item.session!==session.id||item.variation!==activeVariation||item.fen!==viewedGame().fen()||evaluation?.depth<10)return '';pendingSpeechAssessment=null;const note=moveBlunderSpeech(item.move,item.before,evaluation,lang);if(note){chat('system',note);save();renderChat();}return $('speechDetail').value==='tactics'?note:'';}
function speak(text,force=false){if((force||$('audio').checked)&&window.Android)Android.speak(spokenText(text,lang),lang==='de'?'de-DE':'en-US');}
function chat(kind,text,extra={}){const context=['coach','move'].includes(kind)?{ply:replayCursor??game.history().length,fen:viewedGame().fen()}:{};session.chat.push({kind,text,lang,variationId:activeVariation,at:new Date().toISOString(),...context,...extra});}
function notify(text){$('message').textContent=text;chat('system',text);save();renderChat();}
window.nativeMessage=notify;
function save(){if(storageLocked){saveFailed=true;$('saveState').textContent=t('Vorhandene Speicherdaten sind nicht lesbar und werden nicht überschrieben.','Existing saved data cannot be read and will not be overwritten.');return;}if(activeVariation){const v=session.variations.find(v=>v.id===activeVariation);v.moves=game.history({verbose:true}).slice(v.basePly).map(moveObject);}else session.moves=game.history({verbose:true}).map(moveObject);session.activeVariationId=activeVariation;session.mode=analysisMode()?'analysis':'play';session.replayPly=replayCursor;session.updated=new Date().toISOString();session.human=human;const main=activeVariation?restoreGame(session):game;session.result=outcomeText(session,main,'en')||(main.isGameOver()?resultText(main,'en'):null);session.pgn=sessionPgn(session,activeVariation?null:game);if(!session.result&&main.fen()===session.sourceFinalFen&&main.history({verbose:true}).map(uci).join(' ')===session.sourceUci&&['1-0','0-1','1/2-1/2'].includes(session.sourceResult))session.result='Imported result: '+session.sourceResult;archive.activeId=session.id;const i=archive.games.findIndex(s=>s.id===session.id);if(i<0)archive.games.push(session);else archive.games[i]=session;archive.settings={lang,level:$('level').value,audio:$('audio').checked,handsFree:$('handsFree').checked,lcd:$('lcdEnabled').checked,lcdContinuous:$('lcdContinuous').checked,lcdMode,engine:getEngineConfig(),lcdAnalysisTime:$('lcdAnalysisTime').value,speechDetail:$('speechDetail').value};try{localStorage.setItem(archiveKey,JSON.stringify(archive));saveFailed=false;$('saveState').textContent=t('Partie und gesamter Chat automatisch gespeichert.','Game and full chat saved automatically.');}catch{saveFailed=true;$('saveState').textContent=t('Speichern fehlgeschlagen: Gerätespeicher prüfen. Die Partie bleibt vorerst nur im Arbeitsspeicher.','Saving failed: check device storage. This game is currently only in memory.');}renderArchive();}
function renderArchive(){const current=$('archive').value;$('archive').replaceChildren();for(const s of [...archive.games].sort((a,b)=>b.updated.localeCompare(a.updated))){const option=document.createElement('option');option.value=s.id;const date=new Intl.DateTimeFormat(lang==='de'?'de-DE':'en-GB',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Berlin'}).format(new Date(s.created));option.textContent=`${date} · ${Math.ceil(s.moves.length/2)} ${t('Züge','moves')} · ${s.result?t('beendet','finished'):t('offen','in progress')}`;$('archive').append(option);}$('archive').value=archive.games.some(s=>s.id===current)?current:session.id;}
let lastChatView='',lastChatLength=0;
function renderChat(){const container=$('chat'),oldScroll=container.scrollTop,view=viewedGame(),ply=replayCursor??game.history().length,last=view.history({verbose:true}).at(-1),viewKey=session.id+'|'+activeVariation+'|'+ply+'|'+view.fen(),viewChanged=viewKey!==lastChatView,newEntry=session.chat.length>lastChatLength;const nodes=[];let selectedComment=null;for(const entry of session.chat){const item=document.createElement('article');item.className='chat-item '+entry.kind;if((entry.variationId||null)===positionLineId(session,activeVariation,ply)&&Number(entry.ply)===ply&&(entry.kind==='move'&&(entry.fen?entry.fen===view.fen():entry.san===last?.san)||entry.kind==='coach'&&entry.fen===view.fen())){item.classList.add('current-position');item.dataset.ply=String(ply);if(entry.kind==='move'){if(selectedComment){selectedComment.classList.remove('current-position');selectedComment.removeAttribute('aria-current');}selectedComment=item;item.setAttribute('aria-current','true');}}const heading=document.createElement('small');if(entry.kind==='move')heading.textContent=(entry.variationId?t('Variante · ','Variation · '):'')+`${entry.number||Math.ceil(entry.ply/2)}${entry.color==='w'?'.':'...'} ${entry.san} · ${(session.analysis||entry.variationId)?t(entry.color==='w'?'Weiß':'Schwarz',entry.color==='w'?'White':'Black'):entry.color===human?t('Du','You'):t('Stockfish','Stockfish')}`;else heading.textContent=entry.kind==='input'?t('Du','You'):entry.kind==='coach'?t('Schachtrainer','Chess tutor'):entry.kind==='summary'?t('Partiezusammenfassung','Game summary'):t('SprachSchach','SprachSchach');const p=document.createElement('p');p.textContent=entry.text;item.append(heading);if(entry.kind==='summary'&&entry.parts){const content=document.createElement('div');content.className='saved-summary';renderSummary(content,entry.parts,lang);item.append(content);}else item.append(p);nodes.push(item);}container.replaceChildren(...nodes);if(viewChanged&&selectedComment)container.scrollTop=selectedComment.offsetTop-8;else if(newEntry&&!viewChanged)container.scrollTop=container.scrollHeight;else if(viewChanged&&ply===0)container.scrollTop=0;else container.scrollTop=oldScroll;lastChatView=viewKey;lastChatLength=session.chat.length;}
function render(){const view=viewedGame(),squares=[],files=human==='w'?'abcdefgh':'hgfedcba',ranks=human==='w'?'87654321':'12345678',last=view.history({verbose:true}).at(-1),targets=selected?view.moves({square:selected,verbose:true}).map(m=>m.to):[];for(const r of ranks)for(const f of files){const sq=f+r,p=view.get(sq),b=document.createElement('button');b.className='square'+((f.charCodeAt(0)+Number(r))%2===0?' dark':'')+(p?.color==='w'?' white':'')+(sq===selected?' selected':'')+([last?.from,last?.to].includes(sq)?' last':'')+(targets.includes(sq)?' target':'');renderPiece(b,p);b.setAttribute('aria-label',sq+(p?' '+t(p.color==='w'?'Weiß':'Schwarz',p.color==='w'?'white':'black')+' '+names[lang][p.type]:''));b.onclick=()=>tap(sq);squares.push(b);}$('board').replaceChildren(...squares);
 $('appMode').value=analysisMode()?'analysis':'play';$('modeLabel').textContent=t('Modus','Mode');$('appMode').options[0].textContent=t('Spiel-Modus · gegen Stockfish','Play mode · against Stockfish');$('appMode').options[1].textContent=t('Analyse-Modus · beide Seiten','Analysis mode · both sides');$('analysisHint').hidden=!analysisMode();$('analysisHint').textContent=t('Analyse / echte Partie: Züge für beide Seiten eingeben. Stockfish spielt nicht automatisch; für einen Tipp fragen oder die LCD-Bewertung einschalten.','Analysis / real game: enter moves for both sides. Ask for a hint or enable the LCD evaluation.');
 $('status').textContent=browsing()?t('Partieansicht · '+(view.turn()==='w'?'Weiß':'Schwarz')+' am Zug.','Game replay · '+(view.turn()==='w'?'White':'Black')+' to move.'):gameEnded()?endedText():busy?t('Computer überlegt …','Computer is thinking …'):analysisMode()?t(view.turn()==='w'?'Weiß am Zug.':'Schwarz am Zug.',view.turn()==='w'?'White to move.':'Black to move.'):view.turn()===human?t('Du bist am Zug.','Your turn.'):t('Computer ist am Zug.','Computer to move.');if(view.isCheck()&&!view.isGameOver())$('status').textContent+=t(' Schach!',' Check!');$('mic').disabled=false;$('submit').disabled=coachBusy;$('undo').disabled=browsing()||(!activeVariation&&!!declaredOutcome(session,game))||importedEnd()||game.history().length===(session.variations?.find(v=>v.id===activeVariation)?.basePly||0)||(session.variations||[]).some(v=>(v.parentId||null)===activeVariation);$('resign').disabled=$('offerDraw').disabled=!!activeVariation||browsing()||gameEnded()||reviewing;$('offerDraw').textContent=t(analysisMode()?'Remis vereinbaren':'Remis anbieten',analysisMode()?'Agree draw':'Offer draw');
 $('history').textContent=game.history({verbose:true}).map(m=>`${m.before.split(' ')[5]}${m.color==='w'?'.':'...'} ${m.san}`).join('  ');$('explanation').textContent=(browsing()?(last?explain(last,view,lang):t('Ausgangsstellung.','Starting position.')):lastText)||t('Willkommen! Tippe Figuren an oder sprich einen Zug.','Welcome! Tap pieces or speak a move.');renderReplay();renderChat();renderReview();renderVoice();renderLcd();}
function cancelLcd(){clearTimeout(lcdRenderTimer);lcdRenderTimer=null;lcdState='loading';lcdEpoch++;lcdClient?.abort();lcdClient=null;lcdFen=null;lcdEvaluation=null;lcdError=false;}
