function commit(m,warning=''){
 const beforePosition=viewedGame();const beforeScore=lcdFen===beforePosition.fen()?lcdEvaluation:null;
 save();if(saveFailed)return;const ply=replayCursor??game.history().length;let continuation;try{continuation=moveContinuation(session,activeVariation,ply,moveObject(m));}catch(e){notify(t('Zug konnte nicht übernommen werden: ','Could not enter move: ')+e.message);return;}
 cancelLcd();selected=null;$('entry').value='';$('message').textContent='';
 if(continuation.kind==='follow'){activeVariation=continuation.id;game=variationGame(session,activeVariation);replayCursor=continuation.ply;ensureVariantChat();const view=viewedGame(),last=view.history({verbose:true}).at(-1);lastText=explain(last,view,lang);save();render();speak(tacticalMoveSpeech(last,view,lang,$('speechDetail').value));return;}
 if(continuation.kind==='fork'){activeVariation=continuation.id;game=variationGame(session,activeVariation);chat('system',t('Abweichender Zug: neue Variante angelegt. Die Hauptpartie bleibt erhalten.','Different move: new variation created. The main game is preserved.'));}
 replayCursor=null;if(!activeVariation){session.review=null;session.outcome=null;}const played=game.move(m);lastText=explain(played,game,lang);chat('move',lastText,{ply:game.history().length,color:played.color,number:Number(played.before.split(' ')[5]),san:played.san,move:moveObject(played)});pendingSpeechAssessment={session:session.id,variation:activeVariation,fen:game.fen(),move:played,before:beforeScore};save();render();speak([warning,tacticalMoveSpeech(played,game,lang,$('speechDetail').value)].filter(Boolean).join(' '));if(!activeVariation&&gameEnded())void reviewGame();}

function pick(moves){if(moves.length===1){pendingChoices=[];if($('choose').open)$('choose').close();commit(moves[0]);void computer();return;}if(!moves.length){const text=t('Kein passender legaler Zug. Zum Beispiel: e2 nach e4.','No matching legal move. Try: e2 to e4.');notify(text);speak(text);return;}pendingChoices=moves;$('chooseTitle').textContent=t('Bitte wähle den gewünschten Zug:','Choose the intended move:');$('choices').replaceChildren();for(const m of moves){const b=document.createElement('button');b.textContent=`${m.from} → ${m.to}${m.promotion?' · '+names[lang][m.promotion]:''}`;b.onclick=()=>{pendingChoices=[];$('choose').close();commit(m);void computer();};$('choices').append(b);}$('choose').showModal();speak(t('Mehrere Züge passen. Sage Option eins, Option zwei oder den Zug mit Start- und Zielfeld.','Several moves match. Say option one, option two, or specify the origin and destination squares.'));}
function tap(sq){const view=viewedGame();if(reviewing||busy||moveBlocked()||(!analysisMode()&&view.turn()!==human))return;const p=view.get(sq);if(selected){const moves=view.moves({square:selected,verbose:true}).filter(m=>m.to===sq);if(moves.length){chat('input',`${selected} → ${sq}`);save();pick(moves);return;}}selected=p?.color===(analysisMode()?view.turn():human)?sq:null;render();}

async function submit(text){
 if(/^(?:in (?:den |the )?)?(?:analyse[- ]?modus|analysis(?: mode)?|spiel[- ]?modus|play mode)(?: (?:wechseln|wechsel|switch))?[.! ]*$/i.test(text)){switchMode(/analyse|analysis/i.test(text)?'analysis':'play');return;}
 if($('gameAction').open){if(/^(bestätigen|bestaetigen|confirm|ja|yes)[.! ]*$/i.test(text))$('actionConfirm').click();else if(/^(abbrechen|cancel|nein|no)[.! ]*$/i.test(text))$('actionCancel').click();return;}
 if(textImporter.voice(text)||importer.voice(text))return;
 const intent=speechIntent(text);if(intent==='camera'){importer.open(true);return;}if(intent==='image'){importer.openImage();return;}if(intent==='import'){textImporter.open();return;}if(intent.startsWith('replay_')){if(intent==='replay_next')$('replayNext').click();else if(intent==='replay_prev')$('replayPrev').click();else if(intent==='replay_end')$('replayEnd').click();else $('replayStart').click();return;}
 if(['resign','draw_offer','variant_new','variant_main'].includes(intent)){if(intent==='resign')$('resign').click();else if(intent==='draw_offer')$('offerDraw').click();else if(intent==='variant_new'){if($('variationNew').disabled){const text=t('Zum Anlegen einer Variante mindestens einen Halbzug zurückgehen.','Go back at least one half-move to create a variation.');notify(text);speak(text);}else $('variationNew').click();}else $('variationMain').click();return;}
 if(intent==='question'){await askQuestion(text);return;}
 if(intent!=='move'){chat('input',text);save();if(intent==='pause'){$('handsFree').checked=false;syncVoice();save();}else if(intent==='repeat')speak(lastText||$('explanation').textContent,true);else if(intent==='undo')$('undo').click();else if(intent==='new')$('new').click();else if(intent==='copy')exportPgn('copyPgn');else if(intent==='share')exportPgn('sharePgn');else if(intent==='save')exportPgn('savePgn');renderChat();return;}
 if(reviewing){notify(t('Bitte in den Analyse-Modus wechseln, um Züge einzugeben.','Switch to analysis mode to enter moves.'));return;}
 if(pendingChoices.length){const words=text.toLowerCase();const number=words.match(/(?:option|nummer|number)\s*(eins|ein|one|zwei|two|drei|three|vier|four|[1-4])/);const map={eins:1,ein:1,one:1,zwei:2,two:2,drei:3,three:3,vier:4,four:4};const chosen=number?pendingChoices[(map[number[1]]||Number(number[1]))-1]:pendingChoices.find(m=>m.promotion&&words.includes(names[lang][m.promotion]));if(chosen){chat('input',text);pendingChoices=[];$('choose').close();commit(chosen);void computer();return;}}
 if(busy||moveBlocked()||(!analysisMode()&&viewedGame().turn()!==human)){const reply=moveBlocked()?t('Die Partie ist beendet. Du kannst weiterhin Fragen stellen oder eine neue Partie starten.','The game is over. You can still ask questions or start a new game.'):t('Der Computer ist noch am Zug. Du kannst in der Zwischenzeit eine Frage stellen.','It is still the computer’s turn. You can ask a question while waiting.');chat('input',text);notify(reply);speak(reply);return;}
 chat('input',text);save();pick(parseMove(viewedGame(),text));
}
window.receiveSpeech=async alternatives=>{
 try{if(!alternatives?.length)return;const first=alternatives[0];if(/^(?:in (?:den |the )?)?(?:analyse[- ]?modus|analysis(?: mode)?|spiel[- ]?modus|play mode)(?: (?:wechseln|wechsel|switch))?[.! ]*$/i.test(first)){await submit(first);return;}if($('gameAction').open){await submit(first);return;}if(textImporter.isOpen()){textImporter.voice(first);return;}if(importer.isOpen()){importer.voice(first);return;}if(browsing()&&speechIntent(first)==='move'){await submit(first);return;}if(speechIntent(first)!=='move'||pendingChoices.length){await submit(first);return;}for(const text of alternatives){if(parseMove(viewedGame(),text).length){await submit(text);return;}}chat('input',t('Gesprochen: ','Spoken: ')+first);const message=t('Erkannt, aber kein legaler Zug: ','Recognized, but no legal move: ')+first;notify(message);speak(message);}
 finally{if(window.Android?.inputFinished)Android.inputFinished();}
};
function syncVoice(){if($('handsFree').checked)$('audio').checked=true;if(window.Android?.setHandsFree)Android.setHandsFree($('handsFree').checked,lang==='de'?'de-DE':'en-US');renderVoice();}
