window.coachAnswer=(id,text,error)=>{if(pendingCoach?.id!==id)return;clearTimeout(pendingCoach.timer);const pending=pendingCoach;pendingCoach=null;if(error)notify(t('OpenAI ist gerade nicht verfügbar. Der lokale Schachtrainer antwortet.','OpenAI is unavailable right now. The local chess tutor will answer.'));pending.resolve(error?pending.fallback:text);};
