 let local;try{local=await localDialogue(snapshot,question,questionLang,async(moves,turn)=>engine.search(moves,turn,{skill:20,nodes:12000,fen:session.startFen}),previous,session.startFen);}catch{local={text:t('Ich kann die Stellung gerade nicht zuverlässig bewerten. Du kannst nach Schachregeln fragen oder die letzte Zugbeschreibung wiederholen lassen.','I cannot reliably assess the position right now. You can ask about chess rules or repeat the last move description.'),context:{board_fen:snapshot.fen(),legal_moves:snapshot.moves()}};}
